package exam;

public class ArtithmaticQuiz2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int processTime = 145;
		int minutes = processTime / 60;
		int seconds = processTime - minutes*60;
		System.out.println(processTime +"은 "+ minutes +" 분이고 " + seconds +"초입니다.");
	}

}
